from pathlib import Path
import json,html,shutil
R=Path(__file__).parent; D=R/'dist'; (D/'notes').mkdir(parents=True,exist_ok=True)
notes=json.loads((R/'content.json').read_text())
css='''*{box-sizing:border-box}body{margin:0;background:#f4f3ed;color:#213d3b;font:16px/1.8 system-ui,sans-serif}a{color:inherit;text-decoration:none}header{max-width:1180px;margin:auto;padding:26px 24px;display:flex;justify-content:space-between;border-bottom:1px solid #ccd3c9}.brand{font-weight:800;letter-spacing:2px}.tag{font-size:12px;letter-spacing:2px;color:#698078}main{max-width:1180px;margin:auto;padding:36px 24px}h1{font-size:clamp(38px,6vw,72px);line-height:1.25;letter-spacing:-2px;margin:20px 0}h2{line-height:1.4}p{color:#59706a}.hero{display:grid;grid-template-columns:1.5fr 1fr;align-items:center;gap:50px;padding:25px 0 65px}.eyebrow{font-size:12px;letter-spacing:3px;color:#59766a}.hero p{max-width:530px}.button{display:inline-block;background:#254b43;color:white;padding:12px 24px;border-radius:5px;margin-top:12px}.art{height:300px;background:#e5e9dc;border-radius:140px 140px 12px 12px;display:grid;place-items:center;position:relative}.art svg{width:90%;height:90%}.art span{position:absolute;bottom:14px;font:12px monospace;color:#687b66}.sectiontop{display:flex;justify-content:space-between;align-items:end;margin:20px 0}.sectiontop h2{font-size:28px;margin:0}.controls{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0}input,select{padding:13px;border:1px solid #ccd3c9;background:transparent;border-radius:4px;font:inherit;color:inherit}input{flex:1;min-width:180px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.card{display:flex;flex-direction:column;padding:28px;background:#fffef9;border:1px solid #d9ddd2;border-radius:8px;transition:transform .2s}.card:hover{transform:translateY(-4px);border-color:#51725c}.number{font:42px Georgia;color:#a3af92}.pill{font-size:12px;background:#e8eddd;padding:4px 10px;border-radius:20px;width:fit-content}.card h3{font-size:22px;margin-bottom:5px}.card p{font-size:14px;flex:1}.card .read{padding-top:18px;border-top:1px solid #e3e6dc;font-size:14px}.strip{margin:48px 0 20px;padding:28px;border-left:3px solid #97aa7d;background:#e9eddf;display:flex;gap:24px;align-items:center}.strip p{margin:0}.article{max-width:800px}.article h1{font-size:42px}.article section{margin:28px 0;background:#fffef9;border:1px solid #dce0d4;padding:25px;border-radius:6px}.article h2{font-size:22px}.formula{font:22px Georgia,serif;background:#edf0e5;padding:20px;color:#274e42;overflow:auto}.article p{white-space:pre-line}details{border-top:1px solid #dce0d4;padding-top:14px}summary{cursor:pointer;font-weight:600}footer{max-width:1180px;margin:30px auto;padding:25px 24px;border-top:1px solid #ccd3c9;color:#738176;font-size:12px;display:flex;justify-content:space-between}a:focus-visible,summary:focus-visible{outline:3px solid #bc8043;outline-offset:4px}[hidden]{display:none!important}@media(max-width:760px){.hero{grid-template-columns:1fr;gap:20px;padding-bottom:25px}.art{height:230px}.grid{grid-template-columns:1fr}.strip{display:block}.tag{letter-spacing:0}.sectiontop{display:block}.article h1{font-size:32px}}'''
(D/'style.css').write_text(css)
def page(title,body,deep=False):
 p='../' if deep else './'
 return f'''<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="機械系核心課程的觀念、公式與解題筆記。"><title>{title}｜機械系解題筆記站</title><link rel="stylesheet" href="{p}style.css"></head><body><header><a class="brand" href="{p}index.html">MECH / NOTES</a><span class="tag">機械系解題筆記站</span></header>{body}<footer><span>MECH / NOTES · 從理解開始解題</span><a href="{p}guide.html">關於這份筆記 ↗</a></footer></body></html>'''
cards=''
for i,n in enumerate(notes,1):
 e=lambda k:html.escape(n[k]);slug=n['slug']
 cards+=f'''<a class="card" data-category="{e('category')}" href="notes/{slug}.html"><span class="number">0{i}</span><span class="pill">{e('category')}</span><h3>{e('title')}</h3><p>{e('summary')}</p><span class="read">閱讀筆記 <span style="float:right">↗</span></span></a>'''
 body=f'''<main class="article"><a href="../index.html">← 所有筆記</a><p class="eyebrow">{e('category')} / NOTE 0{i}</p><h1>{e('title')}</h1><p>{e('summary')}</p>'''
 for key,label in [('goal','學習目標'),('concept','核心觀念'),('formula','公式與使用條件'),('example','一步一步解題'),('mistakes','常見錯誤')]:
  body+=f'<section><h2>{label}</h2><p'+(' class="formula"' if key=='formula' else '')+f'>{e(key)}</p></section>'
 body+=f'<section><h2>換你試試看</h2><p>{e("question")}</p><details><summary>展開答案與解析</summary><p>{e("answer")}</p></details></section><p>內容來源：本站原創教學整理與自編例題，未重製課本題目。</p></main>'
 (D/'notes'/f'{slug}.html').write_text(page(n['title'],body,True))
hero='''<main><section class="hero"><div><span class="eyebrow">A FIELD GUIDE TO MECHANICAL ENGINEERING</span><h1>公式之前，<br>先把觀念搞懂。</h1><p>給正在學習機械工程的你。拆解熱力學與材料力學，從一個觀念、一個例題開始，把「看不懂」變成「我會了」。</p><a class="button" href="#notes">開始閱讀筆記 ↓</a></div><div class="art"><svg viewBox="0 0 360 280" fill="none" aria-label="軸向拉伸示意圖" role="img"><g stroke="#b9c5a9" stroke-width="1"><path d="M30 40H330M30 80H330M30 120H330M30 160H330M30 200H330M30 240H330M60 20V260M100 20V260M140 20V260M180 20V260M220 20V260M260 20V260M300 20V260"/></g><path d="M90 105H270V165H90Z" fill="#f7f7ef" stroke="#365d4c" stroke-width="2"/><path d="M35 135H90M270 135H325M48 125L35 135L48 145M312 125L325 135L312 145" stroke="#365d4c" stroke-width="3"/><path d="M90 195H270M90 185V205M270 185V205" stroke="#365d4c"/><g fill="#365d4c" font-family="Georgia" font-size="22"><text x="168" y="223">L</text><text x="30" y="115">F</text><text x="312" y="115">F</text><text x="140" y="80">σ = F / A</text></g></svg><span>01 / UNDERSTAND THE FUNDAMENTALS</span></div></section><section id="notes"><div class="sectiontop"><div><span class="eyebrow">THE NOTEBOOK</span><h2>從這裡，建立你的理解</h2></div><span id="count">3 篇核心筆記</span></div><div class="controls"><input id="search" type="search" aria-label="搜尋筆記" placeholder="搜尋觀念、公式或關鍵字…"><select id="category" aria-label="科目篩選"><option value="">所有科目</option><option>熱力學</option><option>材料力學</option></select></div><div class="grid">'''
js='''<script>const q=document.querySelector('#search'),c=document.querySelector('#category');function filter(){let count=0;document.querySelectorAll('.card').forEach(x=>{x.hidden=!(x.textContent.toLowerCase().includes(q.value.trim().toLowerCase())&&(!c.value||x.dataset.category===c.value));if(!x.hidden)count++});document.querySelector('#count').textContent=count+' 篇筆記';document.querySelector('#empty').hidden=count!==0}q.addEventListener('input',filter);c.addEventListener('change',filter);</script>'''
(D/'index.html').write_text(page('首頁',hero+cards+'''</div><p id="empty" hidden>沒有符合的筆記，試試其他關鍵字或科目。</p></section><aside class="strip"><strong>學習有脈絡，解題有方向。</strong><p>每一篇都包含觀念、適用條件、自編例題與練習解析。<br>先試著回答，再展開答案，確認自己真的理解。</p></aside></main>'''+js))
(D/'guide.html').write_text(page('關於筆記', '<main class="article"><a href="index.html">← 返回首頁</a><h1>讓每一篇筆記，<br>都有清楚的脈絡。</h1><p>這是一個機械工程基礎課程學習網站，適合用來複習觀念與常見錯誤。公式與例題都標示使用條件；各課程的符號慣例仍應以授課內容為準。</p><section><h2>固定的學習順序</h2><p>學習目標 → 核心觀念 → 公式與使用條件 → 一步一步解題 → 常見錯誤 → 自我練習。</p></section><section><h2>這個網站如何持續擴充？</h2><p>專案透過 AGENTS.md 定義內容、命名、樣式與驗證規則。新增筆記時沿用 JSON 範本，再執行產生器，就會同步產生文章和首頁入口。</p><a class="button" href="AGENTS.md">閱讀 AGENTS.md ↗</a> <a class="button" href="mech-notes-project.zip">下載完整專案 ↓</a></section></main>'))
shutil.copy(R/'AGENTS.md',D/'AGENTS.md')
print('Generated',len(notes),'notes')
